def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    my_d = sum(1 for a in my if a == 'D')
    opp_d = sum(1 for a in op if a == 'D')
    last_me, last_op = history[-1]

    if my_d == 0:
        if opp_d == 0:
            if n == 10:
                return 'D'
            return 'C'
        else:
            if last_op == 'D':
                return 'D'
            return 'C'

    if n == 11 and my_d == 1 and my[10] == 'D':
        return 'C'

    retaliated = False
    for i in range(n - 1):
        if my[i] == 'D' and op[i+1] == 'D':
            retaliated = True
            break

    if opp_d > n // 3:
        return 'D'

    if retaliated:
        if last_op == 'D':
            return 'C'
        return 'C'
    else:
        return 'D'
